async def act(page):
    import io
    import csv
    import asyncio

    # Step 1: Try the KB helper to export the Customers grid as CSV because it may include
    # a cancellations column. This helper is required to be used when applicable.
    try:
        result = await export_customers_csv_via_grid(page, filename="customers_export.csv")
    except Exception:
        result = None

    def extract_max_from_csv_text_for_cancel_column(csv_text: str):
        if not csv_text:
            return None
        f = io.StringIO(csv_text)
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            return None
        # Find any header that looks like cancellations
        cancel_cols = [h for h in reader.fieldnames if 'cancel' in h.lower()]
        if not cancel_cols:
            return None
        col = cancel_cols[0]
        max_val = 0
        for row in reader:
            raw = (row.get(col) or '').strip()
            if raw == '':
                continue
            try:
                v = int(raw)
            except Exception:
                digits = ''.join(ch for ch in raw if ch.isdigit())
                v = int(digits) if digits else 0
            if v > max_val:
                max_val = v
        return max_val

    # If customers CSV had a cancellations-like column, use it and finish.
    if result and isinstance(result, dict) and 'csv' in result:
        csv_text = result['csv']
        max_cancel = extract_max_from_csv_text_for_cancel_column(csv_text)
        if max_cancel is not None:
            # Print only the numeric result
            print(str(max_cancel))
            return

    # Otherwise, export the Orders grid and compute cancellations per customer by parsing the CSV.
    # Use a relative goto as requested.
    await page.goto('/index.php/admin/sales_order/')
    # Give the page a brief moment to render the grid and controls
    await asyncio.sleep(1)

    # Try to find a combobox that can be used to choose CSV for export.
    comboboxes = page.get_by_role('combobox')
    cb_count = await comboboxes.count()
    csv_selected = False
    for i in range(cb_count):
        cb = comboboxes.nth(i)
        # Try direct label selection first
        try:
            await cb.select_option(label='CSV')
            csv_selected = True
            break
        except Exception:
            pass
        # If direct label failed, inspect visible option labels using accessibility-focused API
        try:
            opts_locator = cb.get_by_role('option')
            opts_texts = await opts_locator.all_inner_texts()
            pick = None
            for opt_text in opts_texts:
                if 'csv' in opt_text.lower():
                    # pick the visible text exactly as returned
                    pick = opt_text
                    break
            if pick:
                try:
                    await cb.select_option(label=pick)
                    csv_selected = True
                    break
                except Exception:
                    # fallback: attempt to select by a typical value 'csv'
                    try:
                        await cb.select_option(value='csv')
                        csv_selected = True
                        break
                    except Exception:
                        pass
        except Exception:
            # If we can't inspect options via get_by_role, continue to next combobox
            pass

    # Find an Export button scoped to the page
    export_btns = page.get_by_role('button', name='Export')
    exp_count = await export_btns.count()
    export_button = None
    if exp_count > 0:
        export_button = export_btns.nth(0)
    else:
        # Fallback: scan all buttons and pick one whose inner text contains 'export'
        all_buttons = page.get_by_role('button')
        bcount = await all_buttons.count()
        for i in range(bcount):
            b = all_buttons.nth(i)
            try:
                txt = (await b.inner_text()).strip()
            except Exception:
                txt = ''
            if 'export' in txt.lower():
                export_button = b
                break

    if export_button is None:
        raise RuntimeError('Could not find an Export button on the Orders page')

    # Trigger the download and save it
    async with page.expect_download() as download_info:
        await export_button.click()
    download = await download_info.value
    orders_filename = 'orders_export.csv'
    await download.save_as(orders_filename)

    # Read the CSV file content (try utf-8, fallback to latin-1)
    try:
        with open(orders_filename, 'rb') as f:
            raw_bytes = f.read()
        try:
            csv_text = raw_bytes.decode('utf-8')
        except Exception:
            csv_text = raw_bytes.decode('latin-1')
    except Exception as e:
        raise RuntimeError(f'Failed to read downloaded orders CSV: {e}')

    # Parse orders CSV and count canceled orders per customer
    f = io.StringIO(csv_text)
    reader = csv.DictReader(f)
    if not reader.fieldnames:
        raise RuntimeError('Orders CSV has no header')

    # Identify likely customer identifier column and status column by header substring matching
    cust_col = None
    candidates = ['customer_email', 'email', 'customer', 'customer_name', 'billing_email', 'billing_name', 'customer_id']
    for candidate in candidates:
        for h in reader.fieldnames:
            if candidate in h.lower():
                cust_col = h
                break
        if cust_col:
            break
    status_col = None
    for h in reader.fieldnames:
        if 'status' in h.lower():
            status_col = h
            break
    if not status_col:
        for h in reader.fieldnames:
            if 'state' in h.lower():
                status_col = h
                break

    if not cust_col:
        # fallback to first column if nothing matches
        cust_col = reader.fieldnames[0]

    cancels_by_customer = {}
    for row in reader:
        status = (row.get(status_col) or '').strip().lower() if status_col else ''
        is_canceled = 'cancel' in status
        if not is_canceled:
            continue
        cust = (row.get(cust_col) or '').strip()
        if cust == '':
            cust = '<unknown>'
        cancels_by_customer[cust] = cancels_by_customer.get(cust, 0) + 1

    if not cancels_by_customer:
        max_cancels = 0
    else:
        max_cancels = max(cancels_by_customer.values())

    # Print only the numeric result
    print(str(max_cancels))

